		public override void update()
		{
			base.update();
			if (count == 0 && !startedToRainBlocks && player.x > 350)
			{
				startedToRainBlocks = true;
			}

			if (startedToRainBlocks)
			{
				++count;
				if (count == 30)
				{
					blocks.add(new BlockFalling(player.x - 8, -96, scale, false, true));
				}
				else if (count == 120)
				{
					startedToRainBlocks = false;
				}
			}

			if (player.y > 480)
			{
				instantDeath();
			}

			FlxG.collide<Hans, FlxSprite>(player, blocks, blockCollision);
			FlxG.collide<FlxTilemap, BlockFalling>(level, blocks, blockParticle);
			FlxG.collide(blocks);
		}

		public override void getWell()
		{
			FlxG.bgColor = 4290199552;
		}

		public override void nextLevel()
		{
			FlxG.switchState(new Level29());
		}
	}
